        def _val_to_float_pct(v):
            s = str(v).strip()
            if s.endswith('%'):
                try:
                    val = float(s[:-1])
                except Exception:
                    return None
            else:
                try:
                    val = float(s)
                except Exception:
                    return None
            if -1.0000001 <= val <= 1.0000001:
                return val * 100.0
            return val

        cats_set = set()
